const { openLedger, parseLedgerText, verifyChain } = require(
  "../.swarm/fuzz-build/evidence/ledger.js",
);
const { genesisHash, hashOfRecord, ledgerRecordSchema } = require(
  "../.swarm/fuzz-build/evidence/ledger-record.js",
);

